pub(crate) fn is_unsafe_builtin(name: &str) -> bool {
    matches!(
        name,
        "ptr_read"
            | "ptr_write"
            | "ptr_add"
            | "volatile_read"
            | "volatile_write"
            | "raw_alloc"
            | "raw_free"
            | "raw_memcpy"
            | "raw_memset"
            | "raw_memcmp"
            | "cstr_to_text"
    )
}

pub(crate) fn lookup_builtin(name: &str) -> Option<&'static BuiltinSig> {
    BUILTIN_SIGS.iter().find(|b| b.name == name)
}

